var file_map = map[string]string{

	"clients.baml":                  "// 客户端注册：StepFun（阶跃星辰）OpenAI 兼容网关。\n//\n// 接入面（平台文档 step_plan 推理接口）：BaseURL\n// https://api.stepfun.com/step_plan/v1，Chat Completions 与 OpenAI 协议\n// 逐字段兼容——BAML openai provider 直接可用。凭据零明文入仓（治理 AR-3）：\n// api key 经环境变量 STEPFUN_API_KEY 注入，进程环境透传见\n// baml_client/runtime.go getEnvVars。\n//\n// 模型档位注册化（宪法 A7/D10）：provider/model/model_version 三要素最终\n// 全进 AI 台账——cmd/langgen -provider/-model/-model-version 旗标与本 client\n// 的 options.model 必须同值（D10 台账五要素对齐，见 langgen runReorg 装配链）。\nclient StepFun {\n  provider openai\n  options {\n    model \"step-3.7-flash\"\n    base_url \"https://api.stepfun.com/step_plan/v1\"\n    api_key env.STEPFUN_API_KEY\n  }\n}\n",
	"generators/go.baml":            "// Go 生成器：baml_src → ../baml_client（生成物提交入库，纳入 go build/vet）。\n// 生成命令（版本锁定，防 codegen 漂移）：\n//   npx -y @boundaryml/baml@0.226.1 generate\ngenerator target {\n  output_type \"go\"\n  output_dir \"../\"\n  version \"0.226.1\"\n  // go.mod module 名（生成内部 import 路径用）\n  client_package_name \"github.com/Cloudbird-Software/AI_Web_School\"\n  // 生成后立即格式化（GO-1：生成物同样必须 gofmt 零 diff）\n  on_generate \"gofmt -w .\"\n}\n",
	"generators/lang_sentence.baml": "// W6 语文轮半确定档：句子重组操作员（issue #34 §六三档结构第二档）。\n//\n// 铁律同 operators.baml（宪法 A2/D10 + issue #34 D-A）：LLM 产出永远是 draft。\n// Go 侧 packs/subjectlang.SentenceReorgSolvability 做代码验可解性（独立于 LLM\n// 调用面），全过才成实例；任一检查失败即丢弃 draft（draft 永远是 draft）。\n// 本文件是本母题 prompt 层唯一事实源；Go 侧经 core/ai Caller 注入出站执行面，\n// 测试用 fake Caller，不要求真实 LLM 调用。\n\n// SentenceReorg 是句子重组 draft 的输出契约（与\n// packs/subjectlang.SentenceReorgDraft 的 JSON 字段一一对应）。\nclass SentenceReorg {\n  sentence string @description(#\"题干句子：围绕题材词写成、适合该学段的一句完整中文句子，句中恰好包含一次挖空词\"#)\n  answer string @description(#\"挖空词：句中被挖去的目标词，必须来自入库语料词表（word_in_vocab 判定域）\"#)\n  distractors string[] @description(#\"干扰词数组：恰好 3 个，全部在词表内、两两互异、都不等于挖空词、都不出现在题干句中\"#)\n  explanation string @description(#\"解析：说明挖空词为何恰配该空格（非空，供评价者核查）\"#)\n}\n\n// GenerateSentenceReorg 依据题材词与学段生成一道「选词填空」草稿。\n// vocab_candidates 是入库语料词表全量（逗号分隔）——answer 与 distractors\n// 的判定域：LLM 不知道词表内容时只能凭空造词，校验器必然拒绝（fail-closed\n// 浪费一次出站）；把判定域显式递给出站面，候选即合法域。\nfunction GenerateSentenceReorg(source_word: string, gradeband: string, vocab_candidates: string) -> SentenceReorg {\n  client StepFun // StepFun OpenAI 兼容网关（clients.baml 注册；环境变量 STEPFUN_API_KEY）。Go 侧测试用 fake Caller，不要求真实调用。\n  prompt #\"\n    你是小学语文练习题生成操作员（半确定档：句子重组）。依据题材词与学段，\n    生成一道「选词填空」草稿：一句围绕题材词的完整句子 + 句中挖空词 +\n    3 个干扰词 + 解析。\n\n    规则（Go 侧校验器将逐条复核，任何一条不满足该草稿作废）：\n    1. sentence：一句适合该学段学生的完整中文句子，围绕题材词展开。\n       句子给出完整形式——挖空词原样出现在句中恰好一次；\n       不要自己挖空、不要用括号/下划线/空格代替挖空词（挖空由系统完成）。\n    2. answer（挖空词）：只能从下方词表（vocab_candidates）里选。\n    3. distractors：恰好 3 个干扰词，全部从词表里选；两两互异；都不等于\n       挖空词；都不出现在题干句中（避免多解）。\n    4. explanation：非空，说明挖空词为何恰配该空格。\n\n    题材词（source_word）：{{ source_word }}\n    学段（gradeband）：{{ gradeband }}\n    词表（vocab_candidates，answer 与 distractors 只能从这里选）：\n    {{ vocab_candidates }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\ntest sentence_reorg_golden {\n  functions [GenerateSentenceReorg]\n  args {\n    source_word \"太阳\"\n    gradeband \"L\"\n    vocab_candidates \"太阳,月亮,星星,学校,老师,同学,朋友,上学,读书,写字,说话,听话,看见,听到,走路,跑步,游泳,吃饭,喝水\"\n  }\n}\n",
	"operators.baml":                "// W5-R 操作员（Operator）最小函数（T-W5-030 spike）。\n//\n// 铁律（宪法 A2/D10 + issue #34 D-A）：LLM 产出永远是 draft，只有过校验门、\n// 经写入服务入账的才是内容版本；内容源只来自入库语料（corpus_version 账），\n// LLM 出题不造内容源——结构性杜绝幻觉进题库。\n//\n// 本文件是 prompt 层唯一事实源（languages.yaml llm_prompt 层：allowed=baml，\n// 禁止 prompt 字符串插值进代码）。变更必须过 golden 快照（make baml-golden-check）。\n\n// 生产线四级（宪法 A7：A/B/C/D 四级输出统一 ItemVersion）。\nenum InteractionTier {\n  A @description(#\"结构化母题级（可无限实例化的函数库模板）\"#)\n  B @description(#\"语料驱动变体级\"#)\n  C @description(#\"人工/LLM 单件级草稿\"#)\n  D @description(#\"外采入库级\"#)\n}\n\n// Defining a data model.\nclass DraftInstance {\n  stem string @description(#\"题干（只能使用语料摘录中出现过的实体与措辞）\"#)\n  answer string @description(#\"参考答案\"#)\n  tier InteractionTier @description(#\"该草稿所属生产线档位\"#)\n  source_trace string @description(#\"生成路径说明：母题签名与语料摘录如何进入题干（供评价者核查事实一致性）\"#)\n}\n\n// Create a function to generate a candidate draft instance.\nfunction GenerateDraftInstance(template_signature: string, corpus_excerpt: string) -> DraftInstance {\n  // 模型档位注册化：供应商/模型与采样参数最终全进 AI 台账（D10）。\n  client \"openai/gpt-4o-mini\" // 环境变量 OPENAI_API_KEY；spike 不做真实调用。\n  prompt #\"\n    你是小学练习题生成操作员。依据母题结构签名与入库语料摘录，生成一个候选实例草稿。\n\n    规则：\n    1. 题干只能使用语料摘录中出现过的实体与措辞，不得引入语料之外的事实。\n    2. 保持母题结构签名声明的题型结构与参数槽。\n    3. source_trace 必须指明题干的每一处实体来自语料摘录的哪一句。\n\n    母题结构签名：\n    {{ template_signature }}\n\n    入库语料摘录：\n    {{ corpus_excerpt }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\ntest spike_golden_generate_draft {\n  functions [GenerateDraftInstance]\n  args {\n    template_signature \"{{\\\"interaction\\\":\\\"single_choice\\\",\\\"slots\\\":[\\\"a\\\",\\\"b\\\"]}}\"\n    corpus_excerpt #\"\n      圆是到定点距离等于定长的点的集合。半径为 3 厘米的圆，直径是 6 厘米。\n    \"#\n  }\n}\n",
}

